func ttPush(c *port.Cells, b []byte) int32 {
	// The bytes of an ASCII text blob, as code points.
	var n int32 = port.BlobLen(b)
	var i int32 = 0
	for i < n {
		var v int32 = port.BlobU8(b, i)
		port.CellsPush(c, v)
		i += 1
	}
	return n
}

func ttProd(t *transcriptctx.Tr, k []byte, v []byte) int32 {
	// An ASCII name and value of the producer.
	var kc *port.Cells = port.NewCells()
	var vc *port.Cells = port.NewCells()
	ttPush(kc, k)
	ttPush(vc, v)
	return transcript.TrAddProducer(t, kc, vc)
}

func ttEntry(t *transcriptctx.Tr, round int32, kind int32, id int32, x int32, bitmap int32) int32 {
	// An entry: the request `[4 kind id x]` and the answer `[5 kind id 0 x]`.
	var c *port.Cells = port.NewCells()
	port.CellsPush(c, 4)
	port.CellsPush(c, kind)
	port.CellsPush(c, id)
	port.CellsPush(c, x)
	port.CellsPush(c, 5)
	port.CellsPush(c, kind)
	port.CellsPush(c, id)
	port.CellsPush(c, 0)
	port.CellsPush(c, x)
	return transcript.TrAddEntry(t, round, c, 0, 4, 4, 5, bitmap)
}

func ttKey(c *port.Cells, kind int32, id int32, x int32) int32 {
	// The request record `[4 kind id x]` in `c`, from 0.
	port.CellsDrop(c, 0)
	port.CellsPush(c, 4)
	port.CellsPush(c, kind)
	port.CellsPush(c, id)
	port.CellsPush(c, x)
	return 0
}

