	ttBad(emonT, port.TextBlob("{:emon-transcript 2 :inputs [] :entries []}"), transcript.TbVersion(), "not an emon-transcript of version 1")
	ttBad(emonT, port.TextBlob("{:emon-transcript :1 :inputs [] :entries []}"), transcript.TbVersion(), "not an emon-transcript of version 1")
	ttBad(emonT, port.TextBlob("{:emon-transcript 2 :emon-transcript 1 :inputs [] :entries []}"), transcript.TbVersion(), "not an emon-transcript of version 1")
	ttBad(emonT, port.TextBlob("{:emon-transcript 1}"), transcript.TbNoInputs(), "no :inputs")
	ttBad(emonT, port.TextBlob("{:emon-transcript 1 :inputs 5 :entries []}"), transcript.TbNoInputs(), "no :inputs")
	ttBad(emonT, port.TextBlob("{:emon-transcript 1 :inputs {} :entries []}"), transcript.TbNoInputs(), "no :inputs")
