func TestARequestIsFoundByTheWholeRecord(emonT *testing.T) {
	var t *transcriptctx.Tr = transcriptctx.NewTr()
	var k *port.Cells = port.NewCells()
	ttEntry(t, 0, transcript.TkRender(), 1, 10, 0)
	ttEntry(t, 0, transcript.TkOcr(), 2, 20, 0)
	ttEntry(t, 1, transcript.TkRender(), 3, 30, 0)
	port.AssertEq(emonT, transcript.TrIndex(t), 0, "indexed")
	ttKey(k, transcript.TkOcr(), 2, 20)
	port.AssertEq(emonT, ttFound(t, k), 1, "the second entry is found by its place")
	ttKey(k, transcript.TkRender(), 3, 30)
	port.AssertEq(emonT, ttFound(t, k), 2, "the third")
	ttKey(k, transcript.TkRender(), 3, 31)
	port.AssertEq(emonT, transcript.TrFind(t, k, 0, 4), -1, "one cell different is a miss")
	ttKey(k, transcript.TkDecode(), 3, 30)
	port.AssertEq(emonT, transcript.TrFind(t, k, 0, 4), -1, "another kind is a miss")
	ttKey(k, transcript.TkRender(), 4, 30)
	port.AssertEq(emonT, transcript.TrFind(t, k, 0, 4), -1, "another id is a miss")
	ttKey(k, transcript.TkRender(), 3, 30)
	port.AssertEq(emonT, transcript.TrFind(t, k, 0, 3), -1, "a shorter record is a miss")
	port.CellsPush(k, 9)
	port.AssertEq(emonT, transcript.TrFind(t, k, 0, 5), -1, "a longer record is a miss")
}

func TestARequestFoundInTheMiddleOfCells(emonT *testing.T) {
	var t *transcriptctx.Tr = transcriptctx.NewTr()
	var k *port.Cells = port.NewCells()
	ttEntry(t, 0, transcript.TkOcr(), 5, 50, 0)
	transcript.TrIndex(t)
	port.CellsPush(k, 77)
	port.CellsPush(k, 77)
	port.CellsPush(k, 4)
	port.CellsPush(k, transcript.TkOcr())
	port.CellsPush(k, 5)
	port.CellsPush(k, 50)
	port.CellsPush(k, 88)
	port.AssertEq(emonT, ttFoundAt(t, k, 2, 4), 0, "found at an offset")
	port.AssertEq(emonT, ttFoundAt(t, k, 1, 4), -1, "not at the wrong offset")
}

