func TestOfTwoEntriesOfOneRequestTheLaterAnswers(emonT *testing.T) {
	var t *transcriptctx.Tr = transcriptctx.NewTr()
	var k *port.Cells = port.NewCells()
	ttEntry(t, 0, transcript.TkOcr(), 5, 50, 0)
	ttEntry(t, 0, transcript.TkOcr(), 6, 60, 0)
	ttEntry(t, 3, transcript.TkOcr(), 5, 50, 0)
	transcript.TrIndex(t)
	ttKey(k, transcript.TkOcr(), 5, 50)
	var e int32 = transcript.TrTake(t, k, 0, 4)
	port.AssertEq(emonT, transcript.TrEN(t, e), 2, "the later")
	port.AssertEq(emonT, transcript.TrERound(t, e), 3, "its round")
	ttKey(k, transcript.TkOcr(), 6, 60)
	port.AssertEq(emonT, ttTaken(t, k), 1, "the other request")
	port.AssertEq(emonT, transcript.TrUnused(t), 1, "the earlier of the two was never asked for")
}

func TestTheEntriesNobodyAskedForAreCounted(emonT *testing.T) {
	var t *transcriptctx.Tr = transcriptctx.NewTr()
	var k *port.Cells = port.NewCells()
	var out *strings.Builder = port.NewText()
	ttEntry(t, 0, transcript.TkRender(), 1, 10, 0)
	ttEntry(t, 0, transcript.TkRender(), 2, 20, 0)
	ttEntry(t, 0, transcript.TkRender(), 3, 30, 0)
	transcript.TrIndex(t)
	port.AssertEq(emonT, transcript.TrUnused(t), 3, "all three")
	ttKey(k, transcript.TkRender(), 2, 20)
	port.AssertThat(emonT, transcript.TrTake(t, k, 0, 4) >= 0, "one asked")
	port.AssertEq(emonT, transcript.TrUnused(t), 2, "two left")
	transcript.TrTake(t, k, 0, 4)
	port.AssertEq(emonT, transcript.TrUnused(t), 2, "asking twice counts once")
	ttKey(k, transcript.TkRender(), 2, 21)
	port.AssertEq(emonT, transcript.TrTake(t, k, 0, 4), -1, "a miss marks nothing")
	port.AssertEq(emonT, transcript.TrUnused(t), 2, "still two")
	transcript.TrUnusedMsg(t, out)
	port.AssertText(emonT, out, "2 recorded entries were never asked for", "the sentence of transcript-bad")
}

func TestFindDoesNotMarkAndTakeDoes(emonT *testing.T) {
	var t *transcriptctx.Tr = transcriptctx.NewTr()
	var k *port.Cells = port.NewCells()
	ttEntry(t, 0, transcript.TkRender(), 1, 10, 0)
	transcript.TrIndex(t)
	ttKey(k, transcript.TkRender(), 1, 10)
	port.AssertThat(emonT, transcript.TrFind(t, k, 0, 4) >= 0, "found")
	port.AssertEq(emonT, transcript.TrUnused(t), 1, "find leaves it")
	port.AssertThat(emonT, transcript.TrTake(t, k, 0, 4) >= 0, "taken")
	port.AssertEq(emonT, transcript.TrUnused(t), 0, "take marks it")
}

