func ttMany(emonT *testing.T, n int32) int32 {
	// n entries of distinct requests, every one found by its own record and no other.
	var t *transcriptctx.Tr = transcriptctx.NewTr()
	var k *port.Cells = port.NewCells()
	var i int32 = 0
	for i < n {
		ttEntry(t, i/7, transcript.TkOcr(), i+1, i*3, 0)
		i += 1
	}
	transcript.TrIndex(t)
	i = 0
	for i < n {
		ttKey(k, transcript.TkOcr(), i+1, i*3)
		port.AssertEqAt(emonT, ttTaken(t, k), i, "found at its own place", i)
		ttKey(k, transcript.TkOcr(), i+1, (i*3)+1)
		port.AssertEqAt(emonT, ttFound(t, k), -1, "a neighbour is a miss", i)
		i += 1
	}
	port.AssertEq(emonT, transcript.TrUnused(t), 0, "all asked for")
	return 0
}

